/*
 * MetaLimpia — PDF scrub canary verify script.
 *
 * Validates the js/pdfScrubber.js module end-to-end against a
 * synthetic PDF generated by pdf-lib. Exercises the public
 * scrubPdf() entry point (the same one handlePdfScopeConfirm
 * in js/main.js dynamic-imports at runtime), then asserts:
 *
 *   1. Canary strings are GONE from the output bytes
 *      (the Title / Author / Subject / Keywords / Producer /
 *      Creator fields we stamp on the synthetic PDF must
 *      not appear in the cleaned bytes; same for the XMP
 *      "dc:title" payload and the "PieceInfo" content we
 *      inject into /PieceInfo).
 *
 *   2. Idempotence — running scrubPdf twice on the same
 *      bytes produces byte-identical output (no additional
 *      metadata stamps appear between runs).
 *
 *   3. Document still renders — page count and the page's
 *      visible text content are preserved across the scrub
 *      (we re-load the cleaned bytes with a fresh PDFDocument
 *      and assert getPageCount + the embedded content stream).
 *
 * Run from C:\NodeJS\MetaLimpia-worktrees\pdf-scrubber:
 *   node scripts/verify-pdf-scrubber.mjs
 *
 * Exit code:
 *   0 — every assertion passed.
 *   1 — at least one assertion failed (printed to stderr).
 *
 * Lives alongside verify-pdf-encryption.mjs and follows the
 * same convention (pure Node, no Worker, no Vite).
 */

import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import { scrubPdf } from '../js/pdfScrubber.js';

/**
 * Build a synthetic PDF that carries every category of
 * metadata scrubPdf is supposed to remove. Returns the
 * ArrayBuffer of the serialised PDF bytes.
 *
 * The PDFDocument.create() + page-add + content-stream path
 * gives us:
 *   - an Info dict (Producer / Creator auto-stamped, plus
 *     whatever setTitle/setAuthor/etc. add)
 *   - a /Metadata XMP stream we write manually
 *   - a /PieceInfo dictionary (Adobe-style editor data)
 *
 * Catalog keys (/StructTreeRoot, /AA, /MarkInfo, /Names) are
 * not stamped by create() so we do not need to inject them
 * for the canary — they will simply be absent on the input,
 * and the scrub should still produce a valid PDF. The canary
 * focuses on the metadata that IS present so the assertions
 * are meaningful.
 */
async function buildSyntheticPdf() {
  const pdfDoc = await PDFDocument.create();
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const page = pdfDoc.addPage([400, 200]);
  page.drawText('CANARY_PAGE_TEXT_SHOULD_SURVIVE', {
    x: 40,
    y: 100,
    size: 16,
    color: rgb(0, 0, 0),
    font,
  });

  // --- Info dict entries ---
  pdfDoc.setTitle('CANARY_TITLE_SHOULD_NOT_APPEAR');
  pdfDoc.setAuthor('CANARY_AUTHOR_SHOULD_NOT_APPEAR');
  pdfDoc.setSubject('CANARY_SUBJECT_SHOULD_NOT_APPEAR');
  pdfDoc.setKeywords(['CANARY_KEYWORD_SHOULD_NOT_APPEAR']);
  pdfDoc.setProducer('CANARY_PRODUCER_SHOULD_NOT_APPEAR');
  pdfDoc.setCreator('CANARY_CREATOR_SHOULD_NOT_APPEAR');

  // --- XMP /Metadata stream (canonical Adobe-style schema) ---
  const xmp = `<?xpacket begin="\uFEFF" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/" xmlns:dc="purl.org/dc/elements/1.1/">
  <rdf:RDF xmlns:rdf="www.w3.org/1999/02/22-rdf-syntax-ns#">
    <rdf:Description>
      <dc:title><rdf:Alt><rdf:li xml:lang="x-default">CANARY_XMP_TITLE_SHOULD_NOT_APPEAR</rdf:li></rdf:Alt></dc:title>
      <dc:creator><rdf:Seq><rdf:li>CANARY_XMP_CREATOR_SHOULD_NOT_APPEAR</rdf:li></rdf:Seq></dc:creator>
    </rdf:Description>
  </rdf:RDF>
</x:xmpmeta>
<?xpacket end="w"?>`;
  const metadataStream = pdfDoc.context.stream(xmp, {
    Type: 'Metadata',
    Subtype: 'XML',
  });
  const metadataRef = pdfDoc.context.register(metadataStream);
  pdfDoc.catalog.set(pdfDoc.context.obj('Metadata'), metadataRef);

  // --- /PieceInfo dictionary ---
  const pieceInfo = pdfDoc.context.obj({
    Private: pdfDoc.context.obj({
      CANARY_PIECEINFO_SHOULD_NOT_APPEAR: 'present',
    }),
  });
  const pieceInfoRef = pdfDoc.context.register(pieceInfo);
  pdfDoc.catalog.set(pdfDoc.context.obj('PieceInfo'), pieceInfoRef);

  const bytes = await pdfDoc.save();
  // Return as ArrayBuffer (scrubPdf's expected input shape).
  const ab = new ArrayBuffer(bytes.byteLength);
  new Uint8Array(ab).set(bytes);
  return ab;
}

/**
 * Assert a substring is NOT present in the cleaned bytes.
 * Throws with a clear message on failure.
 */
function assertAbsent(bytes, needle, label) {
  const haystack = new TextDecoder('latin1').decode(bytes);
  if (haystack.includes(needle)) {
    throw new Error(
      `FAIL: ${label} — canary string "${needle}" is still present in cleaned PDF`
    );
  }
}

/**
 * Assert a substring IS present (sanity check that the
 * PDF content we wanted to keep actually survives the
 * scrub — protects against a too-aggressive scrub that
 * removes the page contents too).
 */
function assertPresent(bytes, needle, label) {
  const haystack = new TextDecoder('latin1').decode(bytes);
  if (!haystack.includes(needle)) {
    throw new Error(
      `FAIL: ${label} — expected string "${needle}" is missing from cleaned PDF`
    );
  }
}

/**
 * Assert two byte sequences are identical.
 */
function assertEqualBytes(a, b, label) {
  if (a.byteLength !== b.byteLength) {
    throw new Error(
      `FAIL: ${label} — length mismatch ${a.byteLength} vs ${b.byteLength}`
    );
  }
  const va = new Uint8Array(a);
  const vb = new Uint8Array(b);
  for (let i = 0; i < va.length; i++) {
    if (va[i] !== vb[i]) {
      throw new Error(
        `FAIL: ${label} — bytes differ at offset ${i} (${va[i]} vs ${vb[i]})`
      );
    }
  }
}

/**
 * Inspect the cleaned PDF through pdf-lib's runtime API:
 *   - getTitle / getAuthor / getProducer must be undefined
 *     (Info dict was wiped AND trailerInfo.Info cleared).
 *   - catalog.keys() must NOT contain /Metadata, /PieceInfo,
 *     /StructTreeRoot, /AA, /MarkInfo, /Names.
 *   - trailerInfo.Info must be undefined (cleared).
 *
 * Returns the set of catalog keys for diagnostics.
 *
 * Implementation note: pdf-lib's getTitle/getAuthor/getProducer
 * all call getInfoDict() internally, and getInfoDict() will
 * CREATE a new Info dict when trailerInfo.Info is undefined
 * (mutating the context!). So we snapshot trailerInfo.Info
 * BEFORE invoking the getters, otherwise the assertion would
 * always see the just-created dict's ref instead of undefined.
 */
async function inspectCleanedApi(cleaned) {
  const doc = await PDFDocument.load(cleaned, { updateMetadata: false });
  // Snapshot trailerInfo.Info BEFORE any getter that might
  // lazily create one. This is the actual evidence the scrub
  // cleared the trailer — independent of any side-effect the
  // pdf-lib API has on the context after construction.
  const trailerInfoRef = doc.context.trailerInfo.Info;
  const keys = new Set(doc.catalog.keys().map((k) => k.asString()));
  return {
    pageCount: doc.getPageCount(),
    title: doc.getTitle(),
    author: doc.getAuthor(),
    producer: doc.getProducer(),
    trailerInfoRef,
    catalogKeys: keys,
  };
}

async function run() {
  const original = await buildSyntheticPdf();

  // Pre-flight: original must carry the XMP canary strings
  // (catches a silent regression in buildSyntheticPdf).
  assertPresent(original, 'CANARY_XMP_TITLE_SHOULD_NOT_APPEAR', 'pre-flight original (XMP)');
  assertPresent(original, 'CANARY_XMP_CREATOR_SHOULD_NOT_APPEAR', 'pre-flight original (XMP creator)');

  const once = await scrubPdf(original);
  const twice = await scrubPdf(once);

  // ---- 1. XMP /Metadata stream content gone from bytes ----
  // The XMP stream is the "Title/Author XMP strings" canary
  // the design spec calls out explicitly — pdf-lib serialises
  // XML metadata streams as PDFStream objects whose contents
  // are raw XML text. After scrub the stream itself and the
  // catalog /Metadata reference are gone.
  assertAbsent(once, 'CANARY_XMP_TITLE_SHOULD_NOT_APPEAR', 'XMP /Metadata dc:title');
  assertAbsent(once, 'CANARY_XMP_CREATOR_SHOULD_NOT_APPEAR', 'XMP /Metadata dc:creator');

  // ---- 2. Runtime API checks on the re-loaded cleaned PDF ---
  // These are stronger than byte searches because they cover
  // the Info dict + every catalog key the scrub promises to
  // drop — independent of how pdf-lib chose to compress or
  // encode the indirect objects in this particular output.
  const inspected = await inspectCleanedApi(once);
  if (inspected.title !== undefined) {
    throw new Error(
      `FAIL: getTitle() returned "${inspected.title}" after scrub — expected undefined`
    );
  }
  if (inspected.author !== undefined) {
    throw new Error(
      `FAIL: getAuthor() returned "${inspected.author}" after scrub — expected undefined`
    );
  }
  if (inspected.producer !== undefined) {
    throw new Error(
      `FAIL: getProducer() returned "${inspected.producer}" after scrub — ` +
      `expected undefined (no pdf-lib fingerprint either)`
    );
  }
  if (inspected.trailerInfoRef !== undefined) {
    throw new Error(
      'FAIL: trailerInfo.Info is still set after scrub — expected undefined'
    );
  }
  const SCRUBBED_KEYS = ['/Metadata', '/PieceInfo', '/StructTreeRoot', '/AA', '/MarkInfo', '/Names'];
  const leakedKeys = SCRUBBED_KEYS.filter((k) => inspected.catalogKeys.has(k));
  if (leakedKeys.length > 0) {
    throw new Error(
      `FAIL: catalog still contains scrubbed keys: ${leakedKeys.join(', ')}`
    );
  }

  // ---- 3. Idempotence ----
  assertEqualBytes(once, twice, 'idempotent re-clean');

  // ---- 4. PDF still renders ----
  if (inspected.pageCount !== 1) {
    throw new Error(
      `FAIL: page count changed — original 1, cleaned ${inspected.pageCount}`
    );
  }
  // The page text marker `CANARY_PAGE_TEXT_SHOULD_SURVIVE` is
  // emitted into the content stream as a PDFHexString (because
  // pdf-lib's PDFPage.drawText always wraps Type1 strings in
  // PDFHexString). After inflation the operators look like:
  //
  //   q
  //   BT
  //     ... Tf ...
  //     <43414E415259...> Tj
  //   ET
  //   Q
  //
  // So the literal marker is NOT visible in `once` bytes; we
  // inflate the content stream via Node's built-in zlib and
  // search for the hex-encoded form. pdf-lib's PDFPage.drawText
  // always produces this encoding so the check is deterministic.
  const zlib = await import('node:zlib');
  const cleanedDoc = await PDFDocument.load(once, { updateMetadata: false });
  const page = cleanedDoc.getPage(0);
  const contents = page.node.get(cleanedDoc.context.obj('Contents'));
  let inflated = '';
  if (contents) {
    // Contents is a PDFArray of PDFRefs to PDFRawStreams.
    for (let i = 0; i < contents.size(); i++) {
      const item = contents.get(i);
      const stream = cleanedDoc.context.lookup(item);
      if (
        stream &&
        stream.contents &&
        typeof stream.contents.length === 'number'
      ) {
        inflated += zlib.inflateSync(Buffer.from(stream.contents)).toString('latin1');
      }
    }
  }
  // CANARY_PAGE_TEXT_SHOULD_SURVIVE -> hex:
  const HEX_CANARY = '43414E4152595F504147455F544558545F53484F554C445F53555256495645';
  if (!inflated.includes(HEX_CANARY)) {
    throw new Error(
      'FAIL: page text content does not survive the scrub — ' +
      'CANARY_PAGE_TEXT_SHOULD_SURVIVE missing from inflated content stream'
    );
  }

  console.log('--- MetaLimpia PDF scrubber canary verify ---');
  console.log(`original size:     ${original.byteLength} bytes`);
  console.log(`cleaned size:      ${once.byteLength} bytes`);
  console.log(`cleaned x2x:       ${twice.byteLength} bytes`);
  console.log(`page count:        ${inspected.pageCount}`);
  console.log(`getTitle() === undefined:   yes`);
  console.log(`getAuthor() === undefined:  yes`);
  console.log(`getProducer() === undefined: yes (no pdf-lib fingerprint)`);
  console.log(`trailerInfo.Info cleared:   yes`);
  console.log(`catalog scrubbed keys absent: ${SCRUBBED_KEYS.length}/${SCRUBBED_KEYS.length}`);
  console.log(`idempotent re-clean:         yes`);
  console.log(`page text survives:          yes`);
  console.log();
  console.log('SUCCESS — every assertion passed.');
  console.log('Run from project root: node scripts/verify-pdf-scrubber.mjs');
}

run().catch((err) => {
  console.error(err && err.message ? err.message : err);
  process.exit(1);
});